      { href: '@root/encyclopedia/cointelpro.html', title: 'COINTELPRO', description: 'Links state power, surveillance, and criminalization in a later era.' },
      { href: '@root/generated/pages/george-floyd.html', title: 'George Floyd', description: 'Connects modern policing, protest, and criminal-legal accountability.' }
